package com.mediconnect.prescription.application;
import java.util.*; import com.mediconnect.appointment.application.AppointmentService; import com.mediconnect.appointment.domain.AppointmentEntity; import com.mediconnect.external.drug.*; import com.mediconnect.prescription.api.*; import com.mediconnect.prescription.domain.*; import com.mediconnect.prescription.infrastructure.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class PrescriptionService { private final AppointmentService appointmentService; private final OpenFdaDrugValidationService drugValidationService; private final PrescriptionRepository repository; private final PrescriptionMapper mapper; public PrescriptionService(AppointmentService appointmentService,OpenFdaDrugValidationService drugValidationService,PrescriptionRepository repository,PrescriptionMapper mapper){this.appointmentService=appointmentService;this.drugValidationService=drugValidationService;this.repository=repository;this.mapper=mapper;} @PreAuthorize("hasRole('DOCTOR')") @Transactional public PrescriptionResponse create(String doctorEmail,UUID appointmentId,CreatePrescriptionRequest request){AppointmentEntity appointment=appointmentService.requireAssignedDoctor(doctorEmail,appointmentId);List<ValidatedItem> validatedItems=new ArrayList<>();for(PrescriptionItemRequest item:request.items()){DrugValidationResult result=drugValidationService.validate(item.drugName());validatedItems.add(new ValidatedItem(item,result.validationStatus()));}MedicationValidationStatus overallStatus=overallStatus(validatedItems);PrescriptionEntity prescription=new PrescriptionEntity(appointment,overallStatus);validatedItems.forEach(v->prescription.addItem(new PrescriptionItemEntity(v.request().drugName().trim(),v.request().dose().trim(),v.request().frequency().trim(),v.request().duration().trim(),v.status())));return mapper.toResponse(repository.save(prescription));} private MedicationValidationStatus overallStatus(List<ValidatedItem> items){if(items.stream().anyMatch(i->i.status()==MedicationValidationStatus.MANUAL_VALIDATION_REQUIRED))return MedicationValidationStatus.MANUAL_VALIDATION_REQUIRED;if(items.stream().anyMatch(i->i.status()==MedicationValidationStatus.INVALID))return MedicationValidationStatus.INVALID;return MedicationValidationStatus.VALIDATED;} private record ValidatedItem(PrescriptionItemRequest request,MedicationValidationStatus status){} }
